lib='''def bbox(grid, color=None, pred=None):
    """The (r0,c0,h,w) bounding box of all cells matching a color, predicate, or any non-background cell (color None)."""
    cells=[(i,j) for i,row in enumerate(grid) for j,v in enumerate(row) if (pred(v) if pred else (v!=grid_color(grid)) if color is None else v==color)]
    rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
    return (min(rs),min(cs),max(rs)-min(rs)+1,max(cs)-min(cs)+1) if cells else None

def grid_color(grid):
    """The most common color in the grid (the background)."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def template_of(grid):
    """The largest multi-cell connected cluster of non-background cells, cropped from the grid."""
    from collections import deque
    bg=grid_color(grid); h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]; best=None
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb] and grid[na][nb]!=bg:
                            seen[na][nb]=True; q.append((na,nb))
                if best is None or len(cells)>len(best[0]): best=(cells,)
    cells=best[0]
    r0=min(c[0] for c in cells); c0=min(c[1] for c in cells)
    r1=max(c[0] for c in cells); c1=max(c[1] for c in cells)
    return [[grid[r0+a][c0+b] if (r0+a,c0+b) in set(cells) else None for b in range(c1-c0+1)] for a in range(r1-r0+1)]

def isolated(grid, color):
    """Cells of the given color with no neighbor of any non-background color (single-pixel markers)."""
    bg=grid_color(grid); h,w=len(grid),len(grid[0])
    res=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==color:
                nb=[grid[a][b] for a in range(max(0,i-1),min(h,i+2)) for b in range(max(0,j-1),min(w,j+2)) if (a,b)!=(i,j)]
                if all(v==bg for v in nb): res.append((i,j))
    return res

def stamp_template(grid):
    """Stamp the non-background template cluster verbatim, centered on each isolated marker pixel; template stays."""
    tmpl=template_of(grid); H,W=len(tmpl),len(tmpl[0])
    tmpl_cells=[(a,b,v) for a,row in enumerate(tmpl) for b,v in enumerate(row) if v is not None]
    tmpl_set={(a,b) for a,b,_ in tmpl_cells}
    # rebuild dense template box using actual grid values (holes stay background in stamps)
    bg=grid_color(grid)
    r0=min(a for a,b,_ in tmpl_cells); c0=min(b for a,b,_ in tmpl_cells)
    h=max(a for a,b,_ in tmpl_cells)-r0+1; w=max(b for a,b,_ in tmpl_cells)-c0+1
    box=[[None]*w for _ in range(h)]
    # recover the original cluster window from the grid
    cells={(a-r0,b-c0):v for a,b,v in tmpl_cells}
    out=[row[:] for row in grid]
    markers=isolated(grid, next(v for row in grid for v in row if v!=bg and all(grid[a][b]!=v for a in range(len(grid)) for b in range(len(grid[0])) if (a,b) in set() ) ) if False else _marker_color(grid))
    for i,j in markers:
        r,c=i-h//2, j-w//2
        for a in range(h):
            for b in range(w):
                if (a,b) in cells and 0<=r+a<len(out) and 0<=c+b<len(out[0]):
                    out[r+a][c+b]=cells[(a,b)]
    return out

def _marker_color(grid):
    """The color that appears only as isolated single pixels, distinct from background and template colors."""
    bg=grid_color(grid)
    from collections import Counter
    cnt=Counter(v for row in grid for v in row)
    for v,c in cnt.items():
        if v!=bg and c==1 if False else False: pass
    h,w=len(grid),len(grid[0])
    colors={v for row in grid for v in row if v!=bg}
    for v in colors:
        pos=[(i,j) for i in range(h) for j in range(w) if grid[i][j]==v]
        if len(pos)>1 and all(_isolated_at(grid,i,j,bg) for i,j in pos): return v
    return next(v for v in colors if len([1 for i in range(h) for j in range(w) if grid[i][j]==v])==1) if False else next(iter(colors))

def _isolated_at(grid,i,j,bg):
    h,w=len(grid),len(grid[0])
    nb=[grid[a][b] for a in range(max(0,i-1),min(h,i+2)) for b in range(max(0,j-1),min(w,j+2)) if (a,b)!=(i,j)]
    return all(v==bg for v in nb)
